import React, { useState } from 'react';

interface Props {
  onAsk: (question: string) => void;
}

export function QuestionPanel({ onAsk }: Props) {
  const [question, setQuestion] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!question.trim()) return;
    onAsk(question.trim());
    setQuestion('');
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{
        display: 'flex',
        padding: '12px 20px',
        borderTop: '1px solid #0f3460',
        background: '#16213e',
      }}
    >
      <input
        type="text"
        value={question}
        onChange={e => setQuestion(e.target.value)}
        placeholder="Ask a question about your documents..."
        style={{
          flex: 1,
          padding: '10px 14px',
          background: '#1a1a2e',
          color: '#e0e0e0',
          border: '1px solid #0f3460',
          borderRadius: '6px',
          fontSize: '14px',
          outline: 'none',
        }}
      />
      <button
        type="submit"
        style={{
          marginLeft: '10px',
          padding: '10px 20px',
          background: '#533483',
          color: '#fff',
          border: 'none',
          borderRadius: '6px',
          cursor: 'pointer',
          fontSize: '14px',
          fontWeight: 500,
        }}
      >
        Ask
      </button>
    </form>
  );
}
import React from 'react';
import { QAHistory } from '../../../shared/types';

interface Props {
  history: QAHistory[];
}

/**
 * ConversationHistory - Placeholder component
 *
 * TODO: Implement a full multi-turn conversation history view.
 * For now this displays a basic list of past Q&A exchanges.
 */
export function ConversationHistory({ history }: Props) {
  if (history.length === 0) {
    return (
      <div style={{ padding: '20px', color: '#666', textAlign: 'center', fontSize: '13px' }}>
        No conversation history yet. Ask a question to get started.
      </div>
    );
  }

  return (
    <div style={{ padding: '12px' }}>
      <div style={{ fontSize: '13px', color: '#888', marginBottom: '8px' }}>
        History ({history.length})
      </div>
      {history.map((item, i) => (
        <div key={i} style={{ marginBottom: '8px', fontSize: '12px' }}>
          <div style={{ color: '#a0a0c0' }}>Q: {item.question}</div>
          <div style={{ color: '#888' }}>A: {item.response.answer.substring(0, 80)}...</div>
        </div>
      ))}
    </div>
  );
}
